{
  "issues": [],
  "profile": {
    "personality": {
      "traits": ["细心耐心", "沉默寡言", "务实坚韧"],
      "values": ["家庭责任", "手艺人的本分"],
      "flaws": ["固执，不易接受新样式"]
    },
    "voice": {
      "register": "日常口语，简短直接",
      "accent": "鹿巷本地口音，尾音略拖",
      "habits": ["说话时习惯低头整理手边布料", "常以“嗯”开头回应"],
      "samples": ["嗯，这处开线了，拆了重缝才牢靠。", "补丁挑相近的色，不显眼。", "线头要收干净，穿出去才体面。"]
    },
    "background": "在鹿巷长大，自幼跟长辈学针线，成年后以缝补为生。丈夫早逝，独自拉扯三个孩子。每日在窗边支起矮桌，替邻里改旧衣、缀扣子、补破口。手边总有一盏小灯，做到天黑。日子清苦，但从未让孩子穿破衣出门。",
    "currentConcern": "大儿子郝岩近来话少，常晚归，担心他学坏或在外受欺。",
    "goals": ["把三个孩子平安养大", "攒够布头给每个孩子做一身新衣"],
    "fears": ["孩子生病或受伤，自己无力照应"],
    "knowledge": {
      "unknown": ["鹿巷之外大集市的布价行情", "铁件修补的淬火窍门"]
    },
    "relationships": [
      {
        "with": "npc_pop_bs_004_2",
        "relation": "子女",
        "note": "长子，最近在巷口帮人搬货，回家总说累，问多了就闷头睡。"
      },
      {
        "with": "npc_pop_bs_004_3",
        "relation": "子女",
        "note": "次女，手巧，常帮着穿针引线，但坐不住，爱跑去看河。"
      },
      {
        "with": "npc_pop_bs_004_4",
        "relation": "子女",
        "note": "幼子，黏人，总扯着衣角要听故事，晚上必须挨着睡。"
      }
    ],
    "visibleFeature": "右手食指外侧有一道旧针痕，常年戴一枚磨得发亮的铜顶针。"
  }
}
